/// Simple Rust CLI harness for AI code generation.
#[derive(Parser)]
#[command(name = "ctrl-cli")]
#[command(author = "Generated by Antigravity")]
#[command(version = "0.1.0")]
#[command(about = "Interactive REPL and generate subcommand for code snippets", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate code snippet from a prompt.
    Generate {
        /// Model name override (e.g. glm-5.3-flash, deepseek-chat, gpt-4o-mini).
        #[arg(short, long)]
        model: Option<String>,

        /// Skill to activate for generation (e.g. rust-expert, code-reviewer, web-frontend).
        #[arg(short, long)]
        skill: Option<String>,

        /// Prompt to send to the AI code generation provider.
        #[arg(num_args = 1.., required = true)]
        prompt: Vec<String>,
    },
}

#[derive(Serialize, Deserialize, Clone, Debug)]
struct UserProfile {
    name: String,
    tech_stack: Vec<String>,
    response_language: String,
    coding_style: String,
}

impl Default for UserProfile {
    fn default() -> Self {
        Self {
            name: "galangfjr".to_string(),
            tech_stack: vec![
                "Python".to_string(),
                "TypeScript".to_string(),
                "Rust".to_string(),
                "Zig".to_string(),
            ],
            response_language: "Bahasa Indonesia".to_string(),
            coding_style: "Tulis kode yang bersih (clean code), modern, idiomatik, efisien, dan minim dependensi tidak perlu. Berikan penjelasan ringkas dan solutif.".to_string(),
        }
    }
}

fn load_user_profile() -> UserProfile {
    let home = std::env::var_os("USERPROFILE")
        .or_else(|| std::env::var_os("HOME"))
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    let profile_dir = home.join(".ctrl-cli");
    let profile_path = profile_dir.join("profile.json");

    if profile_path.exists() {
        if let Ok(data) = std::fs::read_to_string(&profile_path) {
            if let Ok(prof) = serde_json::from_str::<UserProfile>(&data) {
                return prof;
            }
        }
    }

    let default_profile = UserProfile::default();
    if std::fs::create_dir_all(&profile_dir).is_ok() {
        if let Ok(json_str) = serde_json::to_string_pretty(&default_profile) {
            let _ = std::fs::write(&profile_path, json_str);
        }
    }
    default_profile
}

